const ContactFooter = () => {
  // Best Practice: Membuat state untuk menangkap inputan user
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    message: ''
  });

  // State untuk efek loading dan sukses agar terasa "mewah & interaktif"
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);

  const handleChange = (e: React.ChangeEvent) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    // Simulasi pengiriman data (Nanti di tahap selanjutnya kita hubungkan ke EmailJS/Backend)
    setTimeout(() => {
      setIsSubmitting(false);
      setIsSuccess(true);
      setFormData({ name: '', email: '', message: '' }); // Reset form

      // Kembalikan tombol ke semula setelah 3 detik
      setTimeout(() => setIsSuccess(false), 3000);
    }, 1500);
  };

  return (









          {/* Bagian Info Kontak */}



Mulai Konsultasi 
Keamanan Anda.


              Hubungi tim ahli kami untuk audit keamanan atau diskusi mengenai solusi proteksi kebakaran yang tepat untuk fasilitas Anda.













Kantor Pusat

Jl. Teknologi No. 88, Kawasan Bisnis
Tangerang, Banten, Indonesia












Telepon & WhatsApp

+62 812 3456 7890












Email

info@famindofast.com




            {/* Google Maps Area */}






          {/* Bagian Form */}





Kirim Pesan



                Nama Lengkap




                Email Perusahaan




                Pesan / Kebutuhan



                {isSubmitting ? (
                  <> Mengirim...</>
                ) : isSuccess ? (
                  <> Pesan Terkirim!</>
                ) : (
                  <> Kirim Permintaan</>
                )}






        {/* --- Bagian Footer Instagram & Copyright tetap sama seperti sebelumnya --- */}








                 Instagram Highlights


Ikuti aktivitas dan pembaruan terbaru kami di sosial media.


              @famindofast 





            {igFeeds.map((feed, idx) => (







            ))}










              PT. Famindo Alfa Spektrum Teknologi















            © {new Date().getFullYear()} PT. FAST. All rights reserved. 
 "Every Second Matters"




  );
};

